@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--ink:#e7e8df;--muted:#a2a59a;--lime:#d8f16e;--orange:#e78c58;--panel:rgba(13,17,14,.91);--line:rgba(231,232,223,.15)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#151a15;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit;cursor:pointer}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#252d27}#game{position:absolute;inset:0;width:100%;height:100%;display:block}#vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 49%,transparent 42%,rgba(5,8,7,.2) 85%,rgba(5,8,7,.58) 130%);z-index:1}.screen{position:absolute;inset:0;z-index:5;display:none}.screen.visible{display:flex}.screen#main-menu{background:linear-gradient(90deg,rgba(8,12,10,.88) 0%,rgba(8,12,10,.62) 39%,rgba(8,12,10,.04) 76%),linear-gradient(0deg,rgba(8,12,10,.55),transparent 25%,transparent 78%,rgba(8,12,10,.28)}.screen#main-menu:after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,transparent 58%,rgba(229,234,216,.06) 58.08%,transparent 58.2%),linear-gradient(0deg,transparent 74%,rgba(229,234,216,.055) 74.08%,transparent 74.2%);mix-blend-mode:screen}.menu-top,.menu-bottom{position:absolute;left:5.2%;right:5.2%;display:flex;align-items:center;justify-content:space-between;z-index:2}.menu-top{top:5.2%}.brand-mark{font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:19px;letter-spacing:.14em;display:inline-flex;align-items:center;gap:10px}.brand-mark i{width:12px;height:12px;background:var(--lime);display:inline-block;transform:rotate(45deg);box-shadow:0 0 18px rgba(216,241,110,.48)}.top-right,.menu-bottom{font-size:9px;letter-spacing:.18em;color:#a6aaa1}.top-right b,.menu-bottom b{color:var(--lime);padding:0 7px}.menu-copy{position:absolute;top:24%;left:10.4%;z-index:2}.eyebrow{font-size:9px;letter-spacing:.22em;color:#d4d7cb;font-weight:700;display:flex;align-items:center;gap:12px;margin:0 0 2