ex{position:absolute;right:5.4%;top:48%;font-family:'Barlow Condensed';font-weight:700;font-size:12px;letter-spacing:.14em;writing-mode:vertical-rl;z-index:2}.side-index span{color:var(--lime);padding:8px 0}.menu-crosshair{position:absolute;right:26%;top:48%;font-size:15px;color:rgba(216,241,110,.62);z-index:2}.corner-tag{position:absolute;bottom:15px;right:20px;z-index:4;font:700 8px 'Barlow Condensed';letter-spacing:.16em;color:rgba(237,239,229,.5);pointer-events:none}.corner-tag span{color:var(--lime);padding:0 4px}#grain{position:absolute;inset:-50%;z-index:8;pointer-events:none;opacity:.04;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");animation:grain .22s steps(2) infinite}.briefing.screen,.screen#briefing{background:rgba(5,8,7,.68);align-items:center;justify-content:center;backdrop-filter:blur(5px)}.brief-card{width:min(650px,90vw);padding:27px 38px 35px;background:linear-gradient(135deg,rgba(23,29,25,.97),rgba(12,16,14,.97));border:1px solid rgba(231,232,223,.18);box-shadow:0 25px 100px #0008;position:relative}.brief-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:32px}.brief-top>span:nth-child(2){font-size:8px;letter-spacing:.16em;color:#9da398}.icon-button{border:0;background:none;font-size:27px;color:#cfd2c6}.brief-card .eyebrow{margin-bottom:16px}.brief-card h2,.result-box h2{font-size:67px;line-height:.78}.brief-description{font-size:12px;line-height:1.75;color:#b8bcb2;max-width:480px;margin:20px 0 22px}.brief-stats{display:grid;grid-template-columns:repeat(3,1fr);padding:14px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.brief-stats div{display:flex;flex-direction:column;gap:6px;border-right:1px solid var(--line);padding-left:15px}.brief-stats div:first-child{padding-left:0}.brief-stats div:last-child{border:0}.brief-stats small,.result-stats small{font-size:8px;letter-spacing:.15em;color:#898f83}.brief-stats b{font:700 12px 'Barlow Condensed';letter-spacing:.08em}.brief-stats .threat{color:#f2a06c}.brief-controls{display:flex;justify-content:space-between;padding:18px 0;color:#e3e7d8;font:700 10px 'Barlow Condensed';letter-spacing:.12em}.brief-controls span{display:flex;flex-direction:column;gap:5px}.brief-controls small{font:500 7px 'DM Sans';letter-spacing:.12em;color:#8f968a}.deploy-button{width:100%;margin-top:5px}.pause-screen{align-items:center;justify-content:center;background:rgba(7,10,8,.64);backdrop-filter:blur(4px)}.pause-box,.result-box{display:flex;flex-direction:column;align-items:flex-start;width:min(410px,90vw);padding:35px;background:rgba(17,22,18,.96);border:1px solid var(--line);box-shadow:0 30px 100px #0009}.pause-box .eyebrow,.result-box .eyebrow{margin:42px 0 18px}.pause-box h2{font-size:82px}.pause-box h2 span{color:var(--lime)}.pause-box>p:not(.eyebrow),.result-box>p:not(.eyebrow){font-size:11px;color:#aeb3a8;margin:13px 0 25px}.pause-box .primary-button,.pause-box .secondary-button,.result-box .primary-button,.result-box .secondary-button{width:100%;margin:5px 0}.pause-box>small{font-size:8px;color:#81877c;letter-spacing:.1em;margin-top:16px}.result-box{width:min(520px,92vw)}.result-box .eyebrow{margin:38px 0 16px}.result-box h2{font-size:75px}.result-stats{display:grid;grid-template-columns:repeat(3,1fr);width:100%;padding:17px 0;margin:3px 0 12px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.result-stats div{display:flex;flex-direction:column;gap:7px}.result-stats b{font:700 26px 'Barlow Condensed';color:var(--lime)}.hidden{display:none!important}.hud{position:absolute;inset:0;z-index:3;pointer-events:none;color:#f0f2e9}.hud-top-left,.hud-top-right{position:absolute;top:25px;display:flex;align-items:flex-start;gap:22px}.hud-top-left{left:28px}.hud-top-right{right:28px;align-items:center}.mission-pill{display:flex;align-items:center;gap:11px;padding:10px 14px;background:linear-gradient(90deg,rgba(12,17,13,.83),rgba(12,17,13,.38));border-left:2px solid var(--lime);min-width:235px}.mission-pill .live-dot{flex:none}.mission-pill small,.mission-pill b{display:block}.mission-pill small{font:700 8px 'DM Sans';letter-spacing:.15em;color:#aeb4a7}.mission-pill b{font:700 14px 'Barlow Condensed';letter-spacing:.09em;margin-top:3px}.compass{display:flex;align-items:center;gap:7px;padding-top:5px;color:#c6cabc;font:700 9px 'Barlow Condensed';letter-spacing:.1em}.compass i{height:1px;width:17px;background:#a5ad9b}.compass b{font-size:13px;color:var(--lime);margin:0 3px}.team-status{display:grid;grid-template-columns:8px auto auto;gap:3px 7px;align-items:center;font:700 9px 'Barlow Condensed';letter-spacing:.11em}.team-status .team-dot{width:6px;height:6px;background:var(--lime);border-radius:50%;grid-row:span 2}.team-status b{color:var(--lime);font-size:11px}.team-status small{grid-column:2/4;font:600 7px 'DM Sans';color:#a7ad9f;letter-spacing:.14em}.wave-badge{border-left:1px solid rgba(255,255,255,.3);padding:3px 0 3px 13px;font:700 8px 'DM Sans';letter-spacing:.14em;color:#b2b7aa}.wave-badge b{color:var(--lime);font:800 16px 'Barlow Condensed';padding-left:5px}.center-marker{position:absolute;left:50%;top:50%;width:17px;height:17px;transform:translate(-50%,-50%);opacity:.85}.center-marker:before,.center-marker:after{content:'';position:absolute;background:#e8f0dd;box-shadow:0 0 4px #000}.center-marker:before{width:1px;height:5px;left:8px;top:0;box-shadow:0 12px 4px #000}.center-marker:after{height:1px;width:5px;top:8px;left:0;box-shadow:12px 0 4px #000}.center-marker i{position:absolute;width:3px;height:3px;border:1px solid var(--lime);border-radius:50%;left:7px;top:7px}.hit-marker{display:none;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:23px;height:23px}.hit-marker.active{display:block}.hit-marker i{position:absolute;background:var(--lime);width:6px;height:1.5px;box-shadow:0 0 5px #000}.hit-marker i:nth-child(1){top:4px;left:0;transform:rotate(45deg)}.hit-marker i:nth-child(2){top:4px;right:0;transform:rotate(-45deg)}.hit-marker i:nth-child(3){bottom:4px;left:0;transform:rotate(-45deg)}.hit-marker i:nth-child(4){bottom:4px;right:0;transform:rotate(45deg)}.hud-bottom-left{position:absolute;left:28px;bottom:27px;min-width:240px}.health-wrap{display:flex;align-items:center;gap:10px}.health-icon{font-size:19px;color:var(--lime);font-weight:bold}.health-info{width:135px}.health-info small{font-size:7px;letter-spacing:.16em;color:#d7dbcf}.health-track{height:4px;background:rgba(240,242,233,.3);margin-top:5px}.health-track i{height:100%;width:100%;display:block;background:var(--lime);transition:width .2s}.health-wrap>b{font:700 19px 'Barlow Condensed';margin-left:3px}.squad-line{display:flex;align-items:center;gap:7px;font:700 7px 'DM Sans';letter-spacing:.11em;color:#bec4b6;margin-top:11px}.squad-pip{width:5px;height:5px;background:var(--lime);border-radius:50%}.hud-bottom-right{position:absolute;right:32px;bottom:20px;display:flex;align-items:flex-end;gap:17px}.weapon-label{display:flex;flex-direction:column;text-align:right}.weapon-label small{font-size:7px;letter-spacing:.12em;color:#bbc1b3}.weapon-label small span{color:var(--lime)}.weapon-label>b{font:800 23px 'Barlow Condensed';letter-spacing:.04em}.weapon-label>b i{font-style:normal;font-weight:400;color:#aab1a2}.weapon-mode{font:700 7px 'DM Sans';letter-spacing:.14em;color:var(--lime)}.ammo{font:600 16px 'Barlow Condensed';display:flex;align-items:center;gap:5px;margin-bottom:3px}.ammo strong{font-size:39px;line-height:1;color:#f1f3e8}.ammo>span{color:#9ba195;font-size:19px}.ammo>b{font-size:17px;color:#bdc2b5}.ammo-icon{font-size:18px;color:var(--lime);margin-left:4px}.weapon-silhouette{font-size:70px;color:rgba(14,18,14,.7);line-height:.8;text-shadow:0 1px 1px #abb1a3;transform:rotate(-2