@media(max-width:700px){.menu-top{left:6%;right:6%;top:4%}.top-right{font-size:7px;letter-spacing:.08em}.menu-copy{left:7%;top:24%}h1{font-size:clamp(66px,17vw,105px)}.tagline{font-size:11px;margin:20px 0 26px}.menu-bottom{left:6%;right:6%;bottom:3%;font-size:6px}.menu-bottom span:last-child{display:none}.mission-note{margin-top:22px}.side-index{right:4%}.menu-crosshair{right:12%}.brief-card{padding:21px 22px 24px}.brief-top>span:nth-child(2){display:none}.brief-card h2{font-size:58px}.brief-description{font-size:11px}.brief-controls{flex-wrap:wrap;gap:12px}.brief-controls span{width:21%}.hud-top-left{left:12px;top:12px}.hud-top-right{right:12px;top:12px}.mission-pill{min-width:0;padding:8px 10px;max-width:205px}.mission-pill b{font-size:12px}.compass{display:none}.minimap-frame{top:72px;right:12px;width:120px;padding:6px}.map-label{font-size:6px}#minimap{width:106px;height:106px}.map-coords{font-size:5px}.team-status{font-size:8px}.wave-badge{display:none}.hud-bottom-left{left:14px;bottom:16px;min-width:0}.health-info{width:105px}.squad-line{font-size:6px;max-width:190px}.hud-bottom-right{right:13px;bottom:13px;gap:8px}.weapon-label{display:none}.ammo strong{font-size:31px}.ammo>b{font-size:14px}.ammo-icon{display:none}.weapon-silhouette{font-size:44px}.mobile-controls{display:block;position:absolute;inset:auto 0 0;height:175px;pointer-events:none}.stick{position:absolute;left:22px;bottom:14px;width:116px;height:116px;pointer-events:auto;touch-action:none}.stick-ring{position:absolute;inset:0;border:1px solid rgba(238,242,223,.35);background:rgba(12,16,13,.17);border-radius:50%}.stick-knob{position:absolute;width:46px;height:46px;left:35px;top:35px;border-radius:50%;background:rgba(215,239,153,.22);border:1px solid rgba(216,241,110,.7);box-shadow:inset 0 0 16px #d8f16e22}.stick small{position:absolute;left:39px;bottom:-13px;font:700 7px 'DM Sans';letter-spacing:.15em;color:#e9eddf}.mobile-actions{position:absolute;right:20px;bottom:24px;display:flex;align-items:flex-end;gap:13px;pointer-events:auto}.mobile-actions button{width:52px;height:52px;border-radius:50%;border:1px solid rgba(231,232,223,.4);background:rgba(12,16,13,.52);color:#ecf0e3;font-size:20px;touch-action:none}.mobile-actions small{display:block;font:600 5px 'DM Sans';letter-spacing:.05em}.mobile-actions .fire-button{width:70px;height:70px;background:rgba(216,241,110,.2);border:1px solid rgba(216,241,110,.85);color:var(--lime);font-size:25px}.hud-bottom-right{bottom:135px}.hud-bottom-left{bottom:135px}.corner-tag{display:none}.pause-box,.result-box{padding:26px}.result-box h2{font-size:64px}.result-stats small{font-size:6px}.result-stats b{font-size:21px}}
@media (max-height:620px) and (min-width:701px){.menu-copy{top:18%}.menu-copy h1{font-size:100px}.tagline{margin:18px 0 20px}.mission-note{margin-top:16px}.brief-card{padding-top:18px;padding-bottom:20px}.brief-top{margin-bottom:18px}.brief-card .eyebrow{margin-bottom:10px}.brief-description{margin:12px 0}.brief-controls{padding:12px 0}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const mini = document.getElementById('minimap');
  const mctx = mini.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = {
    menu: $('main-menu'), briefing: $('briefing'), hud: $('hud'), pause: $('pause-screen'), result: $('result-screen'),
    title: $('brief-title'), desc: $('brief-desc'), force: $('brief-force'), deploy: $('deploy-label'), objective: $('objective-text'), mode: $('hud-mode'),
    health: $('health-bar'), healthVal: $('health-value'), ammo: $('ammo-mag'), reserve: $('ammo-reserve'), team: $('team-count'), status: $('status-text'),
    toast: $('toast'), hit: $('hit-marker'), damage: $('damage-flash'), wave: $('wave-badge'), waveNum: $('wave-badge').querySelector('b'),
    intermission: $('intermission'), resultTitle: $('result-title'), resultEyebrow: $('result-eyebrow'), resultCopy: $('result-copy'),
    kills: $('result-kills'), accuracy: $('result-accuracy'), time: $('result-time')
  };
  const baseMap = [
    '1111111111111111','1000000000000001','1000110001100001','1000110001100001',
    '1000000000000001','1011001111001101','1000000000000001','1001100000011001',
    '1001100000011001','1000000000000001','1011001111001101','1000000000000001',
    '1000110001100001','1000110001100001','1000000000000001','1111111111111111'
  ];
  const MAP = baseMap.map(row => row.split('').map(Number));
  const MAP_W = 16, MAP_H = 16, FOV = Math.PI / 2.85;
  const WALL_TEXTURE = document.createElement('canvas'); WALL_TEXTURE.width = 256; WALL_TEXTURE.height = 256;
  const wt = WALL_TEXTURE.getContext('2d');
  function makeWallTexture() {
    const g = wt.createLinearGradient(0,0,256,256); g.addColorStop(0,'#666759');g.addColorStop(.45,'#4d5045');g.addColorStop(1,'#343a34');wt.fillStyle=g;wt.fillRect(0,0,256,256);
    for(let y=0;y<256;y+=48){wt.fillStyle='rgba(13,17,14,.34)';wt.fillRect(0,y,256,3);for(let x=(y/48%2)*30;x<256;x+=62){wt.fillRect(x,y,3,48);wt.fillStyle='rgba(200,192,158,.08)';wt.fillRect(x+4,y+4,52,1)}}
    for(let i=0;i<320;i++){wt.fillStyle=i%3?'rgba(13,17,14,.09)':'rgba(224,217,185,.06)';wt.fillRect(Math.random()*256,Math.random()*256,Math.random()*4+1,Math.random()*5+1)}
    wt.fillStyle='rgba(24,31,26,.46)';wt.fillRect(16,18,42,19);wt.fillStyle='#c9d2a0';wt.font='bold 9px sans-serif';wt.fillText('KESTREL  /  04',20,31);
    wt.fillStyle='rgba(11,14,12,.54)';wt.fillRect(0,217,256,39);wt.fillStyle='rgba(211,224,190,.16)';for(let x=12;x<256;x+=44)wt.fillRect(x,226,24,1);
  }
  makeWallTexture();
  const floorPattern = document.createElement('canvas'); floorPattern.width=128; floorPattern.height=128;
  const fp=floorPattern.getContext('2d'); const fg=fp.createLinearGradient(0,0,128,128);fg.addColorStop(0,'#333a31');fg.addColorStop(1,'#232a24');fp.fillStyle=fg;fp.fillRect(0,0,128,128);
  for(let i=0;i<260;i++){const c=Math.random()>.5?'rgba(180,170,135,.13)':'rgba(5,9,7,.2)';fp.fillStyle=c;fp.fillRect(Math.random()*128,Math.random()*128,Math.random()*3+1,Math.random()*3+1)}
  fp.strokeStyle='rgba(195,191,158,.08)';fp.lineWidth=1;fp.strokeRect(1,1,126,126);fp.beginPath();fp.moveTo(0,64);fp.lineTo(128,64);fp.moveTo(64,0);fp.lineTo(64,128);fp.stroke();

  const state={running:false,paused:false,mode:'campaign',player:{x:1.55,y:1.55,a:.36,hp:100,ammo:30,reserve:120},bots:[],decor:[],kills:0,shots:0,hits:0,start:0,elapsed:0,last:0,fireAt:0,reloadAt:0,flash:0,shake:0,bob:0,wave:1,wavePause:0,objectiveStage:0,toastTimer:0,keys:{},mouse:{x:0,y:0,down:false},touch:{x:0,y:0,fire:false},mapOpen:true,terminal:{x:14.45,y:14.4}};
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), dist=(x,y)=>Math.hypot(x,y), normAngle=a=>Math.atan2(Math.sin(a),Math.cos(a));
  function resize(){const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize);resize();
  function showScreen(screen){[ui.menu,ui.briefing,ui.pause,ui.result].forEach(s=>s.classList.remove('visible'));if(screen)screen.classList.add('visible')}
