function botShoot(bot){const p=state.player;if(!clearPath(bot.x,bot.y,p.x,p.y))return;const d=dist(bot.x-p.x,bot.y-p.y);if(d>11)return;const chance=clamp(1.3-d*.09,.3,.85);if(Math.random()<chance){p.hp=Math.max(0,p.hp-(d<4?12:7));state.shake=.12;ui.damage.style.opacity='.72';setTimeout(()=>ui.damage.style.opacity='0',150);ui.health.style.width=`${p.hp}%`;ui.healthVal.textContent=p.hp;ui.status.textContent='SOB FOGO — PROCURE COBERTURA';if(p.hp<=0)finishGame(false)}}
function updateBots(dt){for(const b of state.bots){if(!b.alive)continue;const p=state.player;b.cooldown-=dt;b.walk+=dt*4;const d=dist(p.x-b.x,p.y-b.y);b.angle=Math.atan2(p.y-b.y,p.x-b.x);if(d<9&&clearPath(b.x,b.y,p.x,p.y)){if(d>3.2){const speed=b.speed*(d<5?.45:1);const dx=Math.cos(b.angle)*speed*dt,dy=Math.sin(b.angle)*speed*dt;if(!blocked(b.x+dx,b.y))b.x+=dx;if(!blocked(b.x,b.y+dy))b.y+=dy;}if(b.cooldown<=0){botShoot(b);b.cooldown=rand(.8,1.8)}}else{b.wander-=dt;if(b.wander<=0){b.angle=rand(-Math.PI,Math.PI);b.wander=rand(1.4,4)}const dx=Math.cos(b.angle)*b.speed*.25*dt,dy=Math.sin(b.angle)*b.speed*.25*dt;if(!blocked(b.x+dx,b.y))b.x+=dx;if(!blocked(b.x,b.y+dy))b.y+=dy}}}
function update(dt){if(!state.running||state.paused)return;state.elapsed=(performance.now()-state.start)/1000;const p=state.player;const forward=(state.keys.KeyW||state.keys.ArrowUp?1:0)-(state.keys.KeyS||state.keys.ArrowDown?1:0);const side=(state.keys.KeyD?1:0)-(state.keys.KeyA?1:0);const moving=forward||side||Math.hypot(state.touch.x,state.touch.y)>.08;const run=state.keys.ShiftLeft||state.keys.ShiftRight;const speed=(run?3.5:2.45)*dt;
