function draw(){const w=innerWidth,h=innerHeight,p=state.player;ctx.save();if(state.shake>0)ctx.translate(rand(-3,3)*state.shake*7,rand(-2,2)*state.shake*6);const horizon=h*.49+Math.sin(state.bob)*2;const sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#1c2829');sky.addColorStop(.62,'#59645c');sky.addColorStop(1,'#a29470');ctx.fillStyle=sky;ctx.fillRect(0,0,w,horizon+1);
