const { chromium, devices } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('fs');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/local/share/chromium/chrome-linux/chrome', args: ['--no-sandbox', '--disable-gpu'] });
  const errors = [];
  const desktop = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  desktop.on('pageerror', e => errors.push(`desktop: ${e.message}`));
  const source = fs.readFileSync('/home/runner/work/remake_mw/remake_mw/game.js', 'utf8').replace(/\}\)\(\);\s*$/, 'window.__emberDebug={state,shoot,reload,update,finishGame,spawnWave};})();');
  await desktop.route('**/game.js', route => route.fulfill({ status: 200, contentType: 'application/javascript', body: source }));
  await desktop.goto('http://localhost:3000');
  await desktop.screenshot({ path: '/tmp/opencode/ember-menu-validated.png' });
  await desktop.locator('#campaign-button').click();
  const brief = await desktop.locator('#briefing').evaluate(e => e.classList.contains('visible'));
  await desktop.locator('#deploy-button').click();
  await desktop.waitForTimeout(300);
  await desktop.screenshot({ path: '/tmp/opencode/ember-campaign-validated.png' });
  const start = await desktop.evaluate(() => ({ hud: !document.querySelector('#hud').classList.contains('hidden'), ammo: document.querySelector('#ammo-mag').textContent, enemies: __emberDebug.state.bots.length }));
  await desktop.evaluate(() => { __emberDebug.state.player.ammo = 24; document.querySelector('#ammo-mag').textContent = '24'; document.dispatchEvent(new KeyboardEvent('keydown', { code: 'KeyR', bubbles: true })); });
  await desktop.waitForTimeout(1250);
  const reload = await desktop.evaluate(() => ({ ammo: __emberDebug.state.player.ammo, reserve: __emberDebug.state.player.reserve, toast: document.querySelector('#toast').textContent }));
  await desktop.keyboard.press('Escape');
  const paused = await desktop.locator('#pause-screen').evaluate(e => e.classList.contains('visible'));
  await desktop.locator('#resume-button').click();
  const resumed = await desktop.evaluate(() => __emberDebug.state.running && !__emberDebug.state.paused);
  // Exercise all campaign enemies, objective transition, terminal extraction, and result stats deterministically.
  await desktop.evaluate(async () => {
    const d = __emberDebug, s = d.state, p = s.player;
    p.hp = 100;
    for (const b of s.bots) {
      b.x = p.x + 1.2; b.y = p.y; b.hp = 100; b.alive = true;
      p.a = 0;
      for (let n = 0; n < 4 && b.alive; n++) { d.shoot(); await new Promise(r => setTimeout(r, 125)); }
    }
    p.x = s.terminal.x - .3; p.y = s.terminal.y; d.update(.016);
  });
  await desktop.waitForTimeout(1250);
  const result = await desktop.evaluate(() => ({ visible: document.querySelector('#result-screen').classList.contains('visible'), title: document.querySelector('#result-title').innerText, kills: document.querySelector('#result-kills').textContent, accuracy: document.querySelector('#result-accuracy').textContent }));
  await desktop.screenshot({ path: '/tmp/opencode/ember-result-validated.png' });
  // Start a real bots match and validate hostile combat and next-wave replenishment.
  await desktop.locator('#result-button').click();
  const matchStart = await desktop.evaluate(() => { const s=__emberDebug.state; return {mode:s.mode, wave:s.wave, enemies:s.bots.length}; });
  await desktop.evaluate(async () => {
    const d=__emberDebug,s=d.state,p=s.player; p.hp=100;
    for (const b of s.bots) { b.x=p.x+1.1; b.y=p.y; b.hp=1; b.alive=true; p.a=0; d.shoot(); await new Promise(r=>setTimeout(r,125)); }
    d.update(.04);
  });
  await desktop.waitForTimeout(2600);
  const wave = await desktop.evaluate(() => ({ wave:__emberDebug.state.wave, enemies:__emberDebug.state.bots.length, ui:document.querySelector('#wave-badge').innerText, running:__emberDebug.state.running }));
  await desktop.screenshot({ path: '/tmp/opencode/ember-match-validated.png' });
  // Mobile layout and touch controls.
  const mobile = await browser.newPage({ ...devices['iPhone 13'], viewport: { width: 390, height: 844 } });
  mobile.on('pageerror', e => errors.push(`mobile: ${e.message}`));
  await mobile.route('**/game.js', route => route.fulfill({ status: 200, contentType: 'application/javascript', body: source }));
  await mobile.goto('http://localhost:3000');
  const mobileLayout = await mobile.evaluate(() => ({ width:innerWidth, docWidth:document.documentElement.scrollWidth, menuWidth:document.querySelector('#main-menu').scrollWidth, title:document.querySelector('h1').getBoundingClientRect().toJSON() }));
  await mobile.locator('#match-button').tap();
  await mobile.locator('#deploy-button').tap();
  await mobile.waitForTimeout(250);
  const controlsVisible = await mobile.evaluate(() => ['#move-stick','#mobile-fire','#mobile-reload'].map(id=>[id,getComputedStyle(document.querySelector(id)).display,document.querySelector(id).getBoundingClientRect().toJSON()]));
  await mobile.locator('#mobile-fire').tap();
  await mobile.locator('#mobile-reload').tap();
  const touch = await mobile.evaluate(() => ({ ammo:__emberDebug.state.player.ammo, fire:__emberDebug.state.touch.fire, reloadAt:__emberDebug.state.reloadAt, orientation:screen.orientation?.type }));
  await mobile.screenshot({ path: '/tmp/opencode/ember-mobile-validated.png' });
  console.log(JSON.stringify({brief,start,reload,paused,resumed,result,matchStart,wave,mobileLayout,controlsVisible,touch,errors}, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

